const yaoTexts=['初九：潜龙勿用。','九二：见龙在田，利见大人。','九三：君子终日乾乾，夕惕若厉，无咎。','九四：或跃在渊，无咎。','九五：飞龙在天，利见大人。','上九：亢龙有悔。'];
const classics=[['《彖传》','断一卦之大义，解释卦名与卦辞，观上下体与时位。','彖者，言乎象者也；爻者，言乎变者也。'],['《象传》','分大象与小象：大象观上下卦，小象逐爻释义，落实于君子之行。','君子见善则迁，有过则改。'],['《系辞传》','总论《易》之源流、体用与筮法，是理解易学宇宙观的枢纽。','易与天地准，故能弥纶天地之道。'],['《文言传》','专释乾坤二卦，展开元亨利贞与君子之德的深意。','夫大人者，与天地合其德，与日月合其明。'],['《说卦传》','系统说明八卦的取象、方位、性情与万物类象。','天地定位，山泽通气，雷风相薄，水火不相射。'],['《序卦传》','说明六十四卦相承的次序与逻辑，展示变化的链条。','有天地，然后万物生焉；盈天地之间者唯万物。'],['《杂卦传》','以错综互杂之法简要比较诸卦，揭示相反相成。','乾刚坤柔，比乐师忧。'],['《大象传》','从卦象提炼政治、伦理与日用工夫，落在君子修养。','天行健，君子以自强不息。'],['《小象传》','逐条解释爻辞，提示爻位、时势与进退的分寸。','潜龙勿用，阳在下也。'],['《古文十翼》','经传合观，古今注家由此进入象数与义理的会通。','观乎天文，以察时变；观乎人文，以化成天下。']];
const canonicalClassicNames=['《彖传上》','《彖传下》','《象传上》','《象传下》','《系辞传上》','《系辞传下》','《文言传》','《说卦传》','《序卦传》','《杂卦传》'];
const canonicalClassicSummaries=['逐卦断义，说明卦名、卦辞与上下体之大旨。','承接上经，论三十卦之时位与吉凶。','取卦象明君子之用，列上经三十卦大象。','逐卦取象明德，列下经三十四卦大象。','总论天地之道、象数之源与易学体用。','论圣人设卦、观象玩辞与卜筮之道。','专释乾坤，申说元亨利贞与君子之德。','说明八卦取象、方位、性情与万物类象。','说明六十四卦相承的次序与变化的链条。','以错综互杂比较诸卦，见相反相成之理。'];
const canonicalClassicQuotes=['彖者，言乎象者也；爻者，言乎变者也。','刚柔相推而生变化，吉凶者，失得之象也。','君子见善则迁，有过则改。','君子以思不出其位，居贤德而善俗。','易与天地准，故能弥纶天地之道。','易无思也，无为也，寂然不动，感而遂通天下之故。','夫大人者，与天地合其德，与日月合其明。','天地定位，山泽通气，雷风相薄，水火不相射。','物不可穷也，故受之以未济终焉。','乾刚坤柔，比乐师忧。'];
const classicTexts=[
['大哉乾元，万物资始，乃统天。云行雨施，品物流形。大明终始，六位时成，时乘六龙以御天。乾道变化，各正性命，保合大和，乃利贞。首出庶物，万国咸宁。','至哉坤元，万物资生，乃顺承天。坤厚载物，德合无疆。含弘光大，品物咸亨。','蒙，山下有险，险而止，蒙。蒙亨，以亨行时中也。匪我求童蒙，童蒙求我，志应也。','需，须也；险在前也。刚健而不陷，其义不困穷矣。','讼，上刚下险，险而健，讼。讼有孚窒惕，中吉，刚来而得中也。终凶，讼不可成也。'],
['天行健，君子以自强不息。地势坤，君子以厚德载物。','云雷，屯；君子以经纶。山下出泉，蒙；君子以果行育德。','水在天上，需；君子以饮食宴乐。天与水违行，讼；君子以作事谋始。','地中有水，师；君子以容民畜众。地上有水，比；先王以建万国，亲诸侯。','风行天上，小畜；君子以懿文德。上天下泽，履；君子以辨上下，定民志。'],
['地中有山，谦；君子以裒多益寡，称物平施。雷出地奋，豫；先王以作乐崇德。','随风，巽；君子以申命行事。丽泽，兑；君子以朋友讲习。','山附于地，剥；上以厚下安宅。雷在地中，复；先王以至日闭关。','明出地上，晋；君子以自昭明德。明入地中，明夷；君子以莅众用晦而明。','山上有水，蹇；君子以反身修德。雷雨作，解；君子以赦过宥罪。'],
['风雷，益；君子以见善则迁，有过则改。泽上于天，夬；君子以施禄及下，居德则忌。','天下有风，姤；后以施命诰四方。泽上于地，萃；君子以除戎器，戒不虞。','木上有水，井；君子以劳民劝相。泽中有火，革；君子以治历明时。','木上有火，鼎；君子以正位凝命。洊雷，震；君子以恐惧修省。','兼山，艮；君子以思不出其位。山上有木，渐；君子以居贤德善俗。'],
['天尊地卑，乾坤定矣；卑高以陈，贵贱位矣。动静有常，刚柔断矣。方以类聚，物以群分，吉凶生矣。','在天成象，在地成形，变化见矣。是故刚柔相摩，八卦相荡，鼓之以雷霆，润之以风雨。日月运行，一寒一暑。','圣人设卦观象，系辞焉而明吉凶，刚柔相推而生变化。是故吉凶者，失得之象也；悔吝者，忧虞之象也。','易与天地准，故能弥纶天地之道。仰以观于天文，俯以察于地理，是故知幽明之故。','夫《易》，开物成务，冒天下之道。如斯而已者也，是故圣人以通天下之志，以定天下之业，以断天下之疑。'],
['子曰：书不尽言，言不尽意。然则圣人之意，其不可见乎？子曰：圣人立象以尽意，设卦以尽情伪，系辞焉以尽其言。','易有圣人之道四焉：以言者尚其辞，以动者尚其变，以制器者尚其象，以卜筮者尚其占。','是故天生神物，圣人则之；天地变化，圣人效之；天垂象，见吉凶，圣人象之；河出图，洛出书，圣人则之。','君子居则观其象而玩其辞，动则观其变而玩其占，是以自天祐之，吉无不利。','易无思也，无为也，寂然不动，感而遂通天下之故。非天下之至精，其孰能与于此。'],
['乾，元者善之长也；亨者嘉之会也；利者义之和也；贞者事之干也。君子体仁，足以长人；嘉会，足以合礼；利物，足以和义；贞固，足以干事。','坤至柔而动也刚，至静而德方。后得主而有常，含万物而化光。坤道其顺乎，承天而时行。','君子进德修业。忠信，所以进德也；修辞立其诚，所以居业也。知至至之，可与几也；知终终之，可与存义也。','潜龙勿用，何谓也？子曰：龙德而隐者也。不易乎世，不成乎名，遯世无闷，不见是而无闷。乐则行之，忧则违之，确乎其不可拔，潜龙也。','见龙在田，德施普也。终日乾乾，反复道也。或跃在渊，进无咎也。飞龙在天，大人造也。亢龙有悔，盈不可久也。'],
['昔者圣人之作《易》也，将以顺性命之理，是以立天之道曰阴与阳，立地之道曰柔与刚，立人之道曰仁与义。兼三才而两之，故《易》六画而成卦。','天地定位，山泽通气，雷风相薄，水火不相射，八卦相错。数往者顺，知来者逆，是故《易》逆数也。','雷以动之，风以散之，雨以润之，日以烜之，艮以止之，兑以说之，乾以君之，坤以藏之。','乾为天、为圜、为君、为父、为玉、为金、为寒、为冰、为大赤、为良马。坤为地、为母、为布、为釜、为吝啬、为均、为子母牛。','巽为木、为风、为长女；震为雷、为龙、为长男；坎为水、为沟渎、为中男；离为火、为日、为中女；艮为山、为径路、为少男；兑为泽、为少女。'],
['有天地，然后万物生焉。盈天地之间者唯万物，故受之以屯。屯者，盈也；屯者，物之始生也。物生必蒙，故受之以蒙。蒙者，蒙也，物之稚也。','物稚不可不养也，故受之以需。需者，饮食之道也。饮食必有讼，故受之以讼。讼必有众起，故受之以师。','师者，众也；众必有所比，故受之以比。比者，比也；比必有所畜，故受之以小畜。物畜然后有礼，故受之以履。','履而泰，然后安，故受之以泰。泰者，通也；物不可以终通，故受之以否。物不可以终否，故受之以同人。','同人于野，亨；物不可以终同，故受之以大有。大有者，众之所有也。盈不可久，故受之以谦。'],
['乾刚坤柔，比乐师忧。临观之义，或与或求。屯见而不失其居，蒙杂而著。震，起也；艮，止也。损益，盛衰之始也。','大畜，时也；无妄，灾也。萃聚而升不来也。谦轻而豫怠也。噬嗑食也，贲无色也。兑见而巽伏也。','随无故也，蛊则饬也。剥，烂也；复，反也。晋，昼也；明夷，诛也。井通而困相遇也。','革，去故也；鼎，取新也。小过，过也；中孚，信也。丰，多故也；亲寡，旅也。','涣，离也；节，止也。解，缓也；蹇，难也。睽，外也；家人，内也。否泰，反其类也。'],
];
classicTexts[1]=['师，众也；贞，正也。能以众正，可以王矣。刚中而应，行险而顺，以此毒天下，而民从之。','比，吉也。比，辅也，下顺从也。原筮元永贞，无咎，以刚中也。不宁方来，上下应也。','小畜，柔得位而上下应之，曰小畜。健而巽，刚中而志行，乃亨。密云不雨，尚往也。','履，柔履刚也。说而应乎乾，是以履虎尾，不咥人，亨。刚中正，履帝位而不疚，光明也。','泰，小往大来，吉亨，则是天地交而万物通也；上下交而其志同也。内阳而外阴，内健而外顺。','否之匪人，不利君子贞，大往小来，则是天地不交而万物不通也；上下不交而天下无邦也。','同人，柔得位得中，而应乎乾，曰同人。同人曰，同人于野，亨，利涉大川，乾行也。','大有，柔得尊位，大中而上下应之，曰大有。其德刚健而文明，应乎天而时行，是以元亨。'];
let currentView='home', selectedHex=0, selectedWing=0, selectedPrinciple=0, historySelectedId='', filter='all', readingMode='ancient', castState={lines:[],working:false,runId:0,ritual:null,confirmed:false,prepared:false,question:'',sessionId:''}, tenWings=null, hexagramTexts=null, principleLibrary=null;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const searchCharMap=Object.fromEntries([...`傳經數萬與為無後來見龍時國陰陽學觀義禮樂風澤貞變應聖體書辭問斷說損艱廣開閉東門雲氣順處進退長終實虛剛柔動靜險濟師謙豫隨蠱臨頤過離咸恆遯壯晉夷睽蹇解夬姤萃升困井革鼎震巽兌渙節孚過既未`].map((char,index)=>[char,[...`传经数万与为无后来见龙时国阴阳学观义礼乐风泽贞变应圣体书辞问断说损艰广开闭东门云气顺处进退长终实虚刚柔动静险济师谦豫随蛊临颐过离咸恒遁壮晋夷睽蹇解夬姤萃升困井革鼎震巽兑涣节孚过既未`][index]]));
function normalizeSearchText(value){return [...String(value||'').toLowerCase()].map(char=>searchCharMap[char]||char).join('')}
function routeForView(view){if(view==='hexagrams')return `#hexagrams/${selectedHex+1}`;if(view==='classics')return `#classics/${selectedWing+1}`;if(view==='principles')return `#principles/${selectedPrinciple+1}`;if(view==='divination')return `#divination/${$('#view-divination')?.dataset.phase||'prepare'}`;if(view==='history')return historySelectedId?`#history/${encodeURIComponent(historySelectedId)}`:'#history';return '#home'}
function nav(view,updateRoute=true){currentView=view;$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const names={home:'研读总览',hexagrams:'六十四卦',divination:'大衍筮法',history:'占问记录',classics:'十翼与易传',principles:'易理体系'};$('#breadcrumbCurrent').textContent=names[view]||names.home;if(updateRoute&&location.hash!==routeForView(view))history.pushState(null,'',routeForView(view));window.scrollTo({top:0,behavior:'smooth'})}
function applyRoute(){const [view='home',value='']=(location.hash.slice(1)||'home').split('/');if(view==='hexagrams'){selectedHex=Math.max(0,Math.min(63,(Number(value)||1)-1));nav('hexagrams',false);renderHexList();renderHexDetail();return}if(view==='classics'){selectedWing=Math.max(0,Math.min(9,(Number(value)||1)-1));nav('classics',false);renderClassics();return}if(view==='principles'){selectedPrinciple=Math.max(0,Math.min(7,(Number(value)||1)-1));nav('principles',false);renderPrinciples();return}if(view==='divination'){nav('divination',false);setDivinationPhase(value||'prepare',false,false);return}if(view==='history'){try{historySelectedId=decodeURIComponent(value||'')}catch{historySelectedId=''}nav('history',false);renderHistory();return}nav('home',false)}
function hexSearchCorpus(index,hexagram){const source=hexagramTexts?.hexagrams?.[index],suffix=index<30?'shang':'xia',tuan=tenWings?.wings?.find(wing=>wing.id===`tuan-${suffix}`)?.sections?.find(section=>section.number===index+1),xiang=tenWings?.wings?.find(wing=>wing.id===`xiang-${suffix}`)?.sections?.find(section=>section.number===index+1);return [hexagram.join(' '),source?.text,...(source?.lines||[]).flatMap(line=>[line.label,line.text]),tuan?.text,xiang?.text].filter(Boolean).join(' ')}
function renderHexList(){const q=normalizeSearchText(($('#hexSearch')?.value||'').trim());const rows=hexagrams.map((hex,i)=>({hex,i})).filter(({hex,i})=>(filter==='all'||(filter==='upper'?i<30:i>=30))&&(!q||normalizeSearchText(hexSearchCorpus(i,hex)).includes(q)));$('#hexList').innerHTML=rows.map(({hex:h,i})=>`<button type="button" class="hex-row ${i===selectedHex?'selected':''}" data-index="${i}" aria-pressed="${i===selectedHex}"><span class="hex-num">${String(i+1).padStart(2,'0')}</span><span class="hex-glyph">${h[1]}</span><span><span class="hex-row-name">${h[2]}</span><span class="hex-row-trigram">${h[6]}上 · ${h[7]}下</span></span><span class="hex-row-tag">${h[0]}</span></button>`).join('')||'<div class="record-empty">未找到相应卦象</div>';$$('.hex-row').forEach(row=>row.addEventListener('click',()=>{selectedHex=+row.dataset.index;nav('hexagrams');renderHexList();renderHexDetail();if(innerWidth<=680)$('#hexDetail').scrollIntoView({behavior:'smooth',block:'start'})}))}
function renderHexDetail(){const h=hexagrams[selectedHex],source=hexagramTexts?.hexagrams?.[selectedHex],wingSuffix=selectedHex<30?'shang':'xia',tuanWing=tenWings?.wings?.find(w=>w.id===`tuan-${wingSuffix}`),xiangWing=tenWings?.wings?.find(w=>w.id===`xiang-${wingSuffix}`),tuan=tuanWing?.sections?.find(s=>s.number===selectedHex+1),xiang=xiangWing?.sections?.find(s=>s.number===selectedHex+1),yao=source?.lines||yaoTexts.map(text=>{const [label,...rest]=text.split('：');return {label,text:rest.join('：')}});$('#hexDetail').innerHTML=`<div class="detail-top"><div><div class="detail-order">第 ${String(selectedHex+1).padStart(2,'0')} 卦 · ${selectedHex<30?'上经':'下经'}</div><div class="detail-glyph">${h[1]}</div><h2 class="detail-title">${h[2]}</h2><div class="detail-subtitle">${h[6]}上${h[7]}下 · ${h[0]}卦</div></div></div><div class="detail-meaning">${h[3]}</div><div class="detail-section"><h4>卦辞 · THE JUDGMENT</h4><p class="wing-original">${source?.text?textHtml(source.text):h[4]}</p></div><div class="detail-section"><h4>彖传 · 本卦总断</h4><p class="wing-original">${tuan?.text?textHtml(tuan.text):`${h[5]}。观其时，察其位，行其中道。`}</p></div><div class="detail-section"><h4>象传 · 大象与小象</h4><p class="wing-original">${xiang?.text?textHtml(xiang.text):'象传正在载入。'}</p></div><div class="detail-section"><h4>爻辞 · 六爻与用九/用六</h4><div class="yao-list">${yao.map(line=>`<div class="yao-item"><b>${textHtml(line.label)}</b><span>${textHtml(line.text)}</span></div>`).join('')}</div></div>`}
function textHtml(text){return text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n/g,'<br>')}
function wingBookmarks(){try{return JSON.parse(localStorage.getItem('guanxiang-wing-bookmarks')||'[]')}catch{return []}}
function renderClassics(){const grid=$('#classicsGrid'),order=$('#wingOrder');if(!tenWings){order.innerHTML='';grid.innerHTML='<div class="library-loading">十翼原文正在载入…</div>';return}const wings=tenWings.wings,names=wings.map(wing=>wing.title),query=($('#wingSearch')?.value||'').trim(),normalizedQuery=normalizeSearchText(query),bookmarks=wingBookmarks(),visible=wings.map((wing,index)=>({wing,index,sections:query?wing.sections.filter(section=>normalizeSearchText(`${section.hexagram||''}${section.text}`).includes(normalizedQuery)):wing.sections})).filter(item=>(!query||item.sections.length)&&(readingMode==='ancient'||query||item.index===selectedWing));order.innerHTML=names.map((name,index)=>`<button type="button" class="wing-order-item ${index===selectedWing?'active':''}" data-wing="${index}"><span>${String(index+1).padStart(2,'0')}</span>${bookmarks.includes(wings[index].id)?'◆ ':''}${name}</button>`).join('');grid.className=`classics-grid ${readingMode}`;grid.innerHTML=visible.map(({wing,index,sections})=>`<article class="classic-card" id="wing-${index}"><div class="classic-card-head"><div><h3>${names[index]}</h3><span class="classic-subtitle">${canonicalClassicSummaries[index]||'依底本次序编排，保留原文段落。'}</span></div><span>WING ${String(index+1).padStart(2,'0')}</span></div><p class="classic-quote">${canonicalClassicQuotes[index]||'原文 · 依底本录入'}</p><div class="classic-readings">${sections.map((section,j)=>`<div class="classic-reading"><span>${String(section.number||j+1).padStart(2,'0')}</span><p>${section.hexagram?`<button class="reading-ref" data-hex-name="${section.hexagram}">${section.hexagram}</button> `:''}${textHtml(section.text||'')}</p></div>`).join('')}</div></article>`).join('')||'<div class="library-loading">十翼原文中没有找到这个词。</div>';$$('.wing-order-item').forEach(button=>button.addEventListener('click',()=>{selectedWing=+button.dataset.wing;nav('classics');renderClassics();if(readingMode==='ancient')requestAnimationFrame(()=>document.querySelector(`#wing-${selectedWing}`)?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'}))}));$$('.reading-ref').forEach(button=>button.addEventListener('click',()=>{const index=hexagrams.findIndex(hexagram=>hexagram[0]===button.dataset.hexName);if(index<0)return;selectedHex=index;nav('hexagrams');renderHexList();renderHexDetail()}));$$('[data-reading-mode]').forEach(button=>button.classList.toggle('active',button.dataset.readingMode===readingMode));$('#bookmarkWing').textContent=bookmarks.includes(wings[selectedWing].id)?'已收藏本篇':'收藏本篇';$('#wingProgress').textContent=query?`找到 ${visible.reduce((sum,item)=>sum+item.sections.length,0)} 段`:`第 ${selectedWing+1} / 10 篇 · ${wings[selectedWing].sections.length} 段`;if(tenWings.edition)$('#editionNote').textContent=` · 底本：${tenWings.edition}`}
function showNotice(message){const notice=$('#appNotice');if(!notice)return;notice.textContent=message;notice.classList.remove('hidden')}
function lunarDayName(day){const digits=['','一','二','三','四','五','六','七','八','九'];if(day===10)return '初十';if(day<10)return `初${digits[day]}`;if(day<20)return `十${digits[day-10]}`;if(day===20)return '二十';if(day<30)return `廿${digits[day-20]}`;return '三十'}
function renderCalendarMeta(){const target=$('#calendarMeta');if(!target)return;const today=new Date();try{const solar=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'short'}).format(today),parts=new Intl.DateTimeFormat('zh-CN-u-ca-chinese',{year:'numeric',month:'long',day:'numeric'}).formatToParts(today),part=type=>parts.find(item=>item.type===type)?.value||'',lunar=`${part('yearName')}年${part('month')}${lunarDayName(Number(part('day')))}`;target.textContent=`${solar} · 农历${lunar}`}catch{target.textContent=new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric'}).format(today)}}
function applyTheme(theme,persist=false){const dark=theme==='dark';document.body.classList.toggle('dark-mode',dark);const button=$('#themeToggle');if(button){button.setAttribute('aria-pressed',String(dark));button.title=dark?'切换为浅色阅读':'切换为深色阅读'}if(persist)try{localStorage.setItem('guanxiang-theme',theme)}catch(error){console.warn('主题未能保存',error)}}
function initTheme(){let theme='';try{theme=localStorage.getItem('guanxiang-theme')||''}catch{}if(!['light','dark'].includes(theme))theme=globalThis.matchMedia?.('(prefers-color-scheme: dark)').matches?'dark':'light';applyTheme(theme)}
async function loadTenWings(){try{const [wingsResponse,textsResponse,principlesResponse]=await Promise.all([fetch('ten-wings.json'),fetch('hexagram-texts.json'),fetch('principles.json')]);if(!wingsResponse.ok||!textsResponse.ok||!principlesResponse.ok)throw new Error('library response failed');[tenWings,hexagramTexts,principleLibrary]=await Promise.all([wingsResponse.json(),textsResponse.json(),principlesResponse.json()]);$('#appNotice')?.classList.add('hidden');renderClassics();renderHexList();renderHexDetail();renderPrinciples();applyRoute();if(castState.lines.length===6)showResult()}catch(error){showNotice('经典数据未能完整载入，请检查本地服务后刷新页面。当前不会以摘要冒充完整原文。');$('#hexDetail').innerHTML='<div class="library-loading">六十四卦原文载入失败。</div>';$('#classicsGrid').innerHTML='<div class="library-loading">十翼原文载入失败。</div>';$('#principleDetail').innerHTML='<div class="library-loading">易理纲要载入失败。</div>';console.error(error)}}
function renderPrinciples(){const sections=principleLibrary?.sections||[],principleNav=$('#principleNav'),detail=$('#principleDetail');if(!principleNav||!detail)return;if(!sections.length){principleNav.innerHTML='';detail.innerHTML='<div class="library-loading">易理纲要正在载入…</div>';return}selectedPrinciple=Math.min(selectedPrinciple,sections.length-1);principleNav.innerHTML=sections.map((section,index)=>`<button type="button" class="principle-nav-item ${index===selectedPrinciple?'active':''}" data-principle="${index}"><span>${String(index+1).padStart(2,'0')}</span><b>${section.title}</b><small>${section.subtitle}</small></button>`).join('');const section=sections[selectedPrinciple];detail.innerHTML=`<header><div><span class="panel-kicker">${String(selectedPrinciple+1).padStart(2,'0')} · PRINCIPLE</span><h2>${section.title}</h2><p>${section.subtitle}</p></div><blockquote>${section.quote}<cite>——${section.source}</cite></blockquote></header><p class="principle-overview">${section.overview}</p><div class="principle-concepts">${section.concepts.map((concept,index)=>`<section><span>${String(index+1).padStart(2,'0')}</span><div><h3>${concept.name}</h3><p>${concept.text}</p></div></section>`).join('')}</div>`;$$('[data-principle]').forEach(button=>button.addEventListener('click',()=>{selectedPrinciple=+button.dataset.principle;nav('principles');renderPrinciples();detail.scrollIntoView({behavior:'smooth',block:'start'})}))}
function lineName(value){return value===6?'老阴 · 变':value===9?'老阳 · 变':value===8?'少阴':'少阳'}
function renderRecords(){const rec=$('#lineRecords');$('#recordEmpty').classList.toggle('hidden',castState.lines.length>0);rec.innerHTML=castState.lines.map((line,i)=>{const path=line.changes?.length?`<em>${line.changes.map(change=>change.remaining).join(' → ')} ÷ 4</em>`:'';return `<div class="line-record"><strong>${line.value===6?'⚋ ×':line.value===9?'⚊ ○':line.value===8?'⚋':'⚊'}</strong><span>第${i+1}爻 · ${lineName(line.value)}${path}</span><small>${line.value}</small></div>`}).join('')}
function wait(ms){return new Promise(resolve=>setTimeout(resolve,ms))}
function drawYarrowChange(stalks,left){left=Math.max(1,Math.min(stalks-1,Number(left)));const right=stalks-left;const rightAfter=right-1;const leftR=left%4||4;const rightR=rightAfter%4||4;const removed=1+leftR+rightR;return {before:stalks,left,right,rightAfter,leftR,rightR,removed,remaining:stalks-removed}}
function setProcedure(hint,result,active){$('#stageHint').textContent=hint;$('#stageResult').textContent=result||'';$('.procedure-symbol').textContent=active;$('#leftPile').classList.toggle('active',active==='左');$('#rightPile').classList.toggle('active',active==='右')}
function stalkBox(id){return $(`#${id} .stalks`)}
function paintStalks(id,count,kind=''){const box=stalkBox(id);if(!box)return;box.innerHTML='';for(let i=0;i<count;i++){const stalk=document.createElement('span');stalk.className=`stalk ${kind}`;stalk.style.setProperty('--i',i);stalk.style.setProperty('--h',`${48+(i*17+count*3)%22}px`);stalk.style.setProperty('--lean',`${(i*11+count)%9-4}deg`);stalk.style.setProperty('--tone',i%5);box.appendChild(stalk)}}
function moveStalks(fromId,toId,count,kind=''){const from=stalkBox(fromId),to=stalkBox(toId);if(!from||!to)return;const moving=[...from.children].slice(-count);moving.forEach(stalk=>{stalk.className=`stalk ${kind}`;stalk.style.setProperty('--i',to.children.length);to.appendChild(stalk)})}
function markOperation(step){const board=$('#stalkBoard');board.className=`stalk-board ${step?`step-${step}`:''}`;const order=['split','hang','count','return'];$$('#operationRail span').forEach(item=>{const current=item.dataset.operation;item.classList.toggle('active',current===step);item.classList.toggle('done',order.indexOf(current)>=0&&order.indexOf(current)<order.indexOf(step))});if(!step)hideCountingBoard();renderRitualProgress();renderChangeLedger();if(castState.lines.length>=6)setDivinationPhase('result',false)}
function setTotal(value,label='策'){const total=$('#stalkTotal strong');if(!total)return;total.textContent=value;$('#stalkTotal small').textContent=label;total.classList.remove('bump');void total.offsetWidth;total.classList.add('bump')}
function ensureDivinationPhases(){if($('#divinationPhases'))return;const phases=document.createElement('nav');phases.id='divinationPhases';phases.className='divination-phases';phases.setAttribute('aria-label','大衍筮法阶段');phases.innerHTML='<button type="button" data-cast-phase="prepare"><span>壹</span><b>正问与准备</b><small>定其所问</small></button><button type="button" data-cast-phase="cast"><span>贰</span><b>演蓍成卦</b><small>十八变</small></button><button type="button" data-cast-phase="result"><span>叁</span><b>观卦研读</b><small>本卦与之卦</small></button>';$('.divination-intro').after(phases)}
function setDivinationPhase(requested,scroll=true,updateRoute=true){const view=$('#view-divination');if(!view)return;let phase=['prepare','cast','result'].includes(requested)?requested:'prepare';if(phase==='cast'&&!castState.confirmed)phase='prepare';if(phase==='result'&&castState.lines.length<6)phase=castState.confirmed?'cast':'prepare';view.classList.remove('phase-prepare','phase-cast','phase-result');view.classList.add(`phase-${phase}`);view.dataset.phase=phase;$$('[data-cast-phase]').forEach(button=>{const name=button.dataset.castPhase;button.classList.toggle('active',name===phase);button.disabled=(name==='cast'&&!castState.confirmed)||(name==='result'&&castState.lines.length<6);button.setAttribute('aria-current',name===phase?'step':'false')});if(updateRoute&&currentView==='divination'&&location.hash!==routeForView('divination'))history.pushState(null,'',routeForView('divination'));if(scroll)window.scrollTo({top:0,behavior:'smooth'})}
function ensureRitualEnhancements(){if($('#ritualProgress'))return;const progress=document.createElement('div');progress.id='ritualProgress';progress.className='ritual-progress';progress.setAttribute('aria-live','polite');$('#operationRail').after(progress);const counting=document.createElement('div');counting.id='countingBoard';counting.className='counting-board hidden';counting.innerHTML='<section class="count-side"><header><span>天 · 左</span><strong id="leftGroupCount">—</strong></header><div class="quartet-track" id="leftGroups"></div><div class="remainder-row"><span>余</span><div id="leftRemainder"></div></div></section><div class="count-formula" id="countFormula">揲之以四</div><section class="count-side"><header><span>地 · 右</span><strong id="rightGroupCount">—</strong></header><div class="quartet-track" id="rightGroups"></div><div class="remainder-row"><span>余</span><div id="rightRemainder"></div></div></section>';$('#stalkBoard').after(counting);const ledger=document.createElement('div');ledger.id='changeLedger';ledger.className='change-ledger';ledger.setAttribute('aria-label','本爻三变记录');ledger.innerHTML='<div class="ledger-label">本爻三变</div><div class="ledger-slot" data-ledger="0"><b>一变</b><span>待行</span></div><div class="ledger-slot" data-ledger="1"><b>二变</b><span>待行</span></div><div class="ledger-slot" data-ledger="2"><b>三变</b><span>待行</span></div>';counting.after(ledger)}
function renderRitualProgress(){const progress=$('#ritualProgress');if(!progress)return;progress.classList.toggle('hidden',!castState.confirmed);progress.innerHTML='';const completed=castState.lines.length,ritual=castState.ritual;for(let line=0;line<6;line++){const group=document.createElement('div');group.className='progress-line';group.setAttribute('aria-label',`第${line+1}爻`);for(let change=0;change<3;change++){const dot=document.createElement('i'),done=line<completed||(line===completed&&ritual&&change<ritual.history.length),active=line===completed&&ritual&&change===ritual.changeNumber-1;dot.className=`${done?'done ':''}${active?'active':''}`.trim();group.appendChild(dot)}progress.appendChild(group)}const label=document.createElement('span');label.textContent=ritual?`第 ${ritual.lineNumber} 爻 · 第 ${ritual.changeNumber} 变 / 共十八变`:completed===6?'十八变已毕':`已成 ${completed} 爻`;progress.appendChild(label)}
function renderChangeLedger(ritual=castState.ritual,draft=null){const ledger=$('#changeLedger');if(!ledger)return;ledger.classList.toggle('hidden',!castState.prepared);const history=ritual?.history||castState.lines.at(-1)?.changes||[],currentIndex=ritual?ritual.changeNumber-1:-1;$$('#changeLedger .ledger-slot').forEach((slot,index)=>{const item=history[index]||(draft&&index===currentIndex?draft:null);slot.classList.toggle('done',Boolean(history[index]));slot.classList.toggle('current',Boolean(draft&&index===currentIndex&&!history[index]));slot.querySelector('span').textContent=item?`${item.before} − ${item.removed} = ${item.remaining}`:index===currentIndex?'进行中':'待行'})}
