function newSessionId(){if(globalThis.crypto?.randomUUID)return crypto.randomUUID();return `cast-${Date.now()}-${Math.random().toString(36).slice(2,10)}`}
function validChange(change){return change&&[change.before,change.left,change.right,change.rightAfter,change.leftR,change.rightR,change.removed,change.remaining].every(Number.isFinite)&&change.before-change.removed===change.remaining}
function validLine(line){return line&&[6,7,8,9].includes(line.value)&&Array.isArray(line.changes)&&line.changes.length===3&&line.changes.every(validChange)}
function validRitual(ritual,lineCount){if(ritual===null)return true;if(!ritual||ritual.lineNumber!==lineCount+1||ritual.changeNumber<1||ritual.changeNumber>3||ritual.stepIndex<0||ritual.stepIndex>3||!Number.isFinite(ritual.stalks)||!Array.isArray(ritual.history)||!ritual.history.every(validChange))return false;return ritual.change===null||validChange(ritual.change)}
function saveCast(){try{localStorage.setItem('guanxiang-cast-v3',JSON.stringify({version:3,savedAt:new Date().toISOString(),sessionId:castState.sessionId,question:castState.question,confirmed:castState.confirmed,prepared:castState.prepared,lines:castState.lines,ritual:castState.ritual}))}catch(error){console.warn('起卦进度未能保存',error)}}
function loadHistory(){try{const records=JSON.parse(localStorage.getItem('guanxiang-history-v1')||'[]');return Array.isArray(records)?records.filter(record=>record&&typeof record.id==='string'&&typeof record.question==='string'&&Array.isArray(record.lines)&&record.lines.length===6&&record.lines.every(validLine)):[]}catch(error){console.warn('占问记录未能读取',error);return []}}
function saveReadingHistory(originalIndex,changedIndex,moving){if(!castState.sessionId||castState.lines.length!==6||!castState.lines.every(validLine))return;try{const records=loadHistory(),record={id:castState.sessionId,completedAt:new Date().toISOString(),question:castState.question,lines:castState.lines,originalIndex,changedIndex,moving};const existing=records.findIndex(item=>item.id===record.id);if(existing>=0)records[existing]={...records[existing],...record,completedAt:records[existing].completedAt||record.completedAt};else records.unshift(record);localStorage.setItem('guanxiang-history-v1',JSON.stringify(records.slice(0,100)));if(currentView==='history')renderHistory()}catch(error){console.warn('占问记录未能保存',error)}}
function renderHistory(){const list=$('#historyList'),detail=$('#historyDetail');if(!list||!detail)return;const records=loadHistory();$('#historyCount').textContent=records.length;if(!records.length){historySelectedId='';list.innerHTML='<div class="history-empty"><span>☷</span><b>尚无占问记录</b><p>完成一次十八变后，卦象与所问会保存在这里。</p></div>';detail.innerHTML='<div class="history-detail-empty">每一条记录都只保存在当前浏览器。</div>';return}if(!records.some(record=>record.id===historySelectedId))historySelectedId=records[0].id;list.innerHTML=records.map(record=>{const original=hexagrams[record.originalIndex],changed=hexagrams[record.changedIndex],date=new Date(record.completedAt);return `<button type="button" class="history-item ${record.id===historySelectedId?'active':''}" data-history-id="${textHtml(record.id)}"><span class="history-glyph">${original?.[1]||'—'}<i>→</i>${changed?.[1]||'—'}</span><span><b>${textHtml(record.question)}</b><small>${Number.isNaN(date.getTime())?'时间未记录':date.toLocaleString('zh-CN',{month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small></span></button>`}).join('');$$('.history-item').forEach(button=>button.addEventListener('click',()=>{historySelectedId=button.dataset.historyId;nav('history');renderHistory()}));renderHistoryDetail(records.find(record=>record.id===historySelectedId))}
function renderHistoryDetail(record){const detail=$('#historyDetail');if(!detail||!record)return;const original=hexagrams[record.originalIndex],changed=hexagrams[record.changedIndex],moving=Array.isArray(record.moving)?record.moving:record.lines.map((line,index)=>line.value===6||line.value===9?index:-1).filter(index=>index>=0),date=new Date(record.completedAt);detail.innerHTML=`<header><span class="panel-kicker">占问存录</span><time>${Number.isNaN(date.getTime())?'':date.toLocaleString('zh-CN')}</time></header><blockquote>${textHtml(record.question)}</blockquote><div class="history-result"><span>${original?.[1]||'—'}</span><i>→</i><span>${changed?.[1]||'—'}</span></div><h2>${original?.[2]||'本卦'}之${changed?.[2]||'变卦'}</h2><p>${moving.length?`动爻：${moving.map(index=>['初','二','三','四','五','上'][index]).join('、')}爻`:'六爻皆静'}</p><div class="history-lines">${record.lines.map((line,index)=>`<div><b>${['初','二','三','四','五','上'][index]}</b><span>${line.value===6?'⚋ ×':line.value===9?'⚊ ○':line.value===8?'⚋':'⚊'}</span><small>${lineName(line.value)}</small></div>`).reverse().join('')}</div><button type="button" class="secondary-button" data-history-hex="${record.originalIndex}">打开本卦全文</button>`;detail.querySelector('[data-history-hex]')?.addEventListener('click',event=>{selectedHex=Number(event.currentTarget.dataset.historyHex)||0;nav('hexagrams');renderHexList();renderHexDetail()})}
function updateCastButton(){const button=$('#castButton'),ritual=castState.ritual;if(!castState.confirmed){button.innerHTML='请先确认问题';button.disabled=true;return}if(!castState.prepared){button.innerHTML='亲手虚一策 · 象太极 <span>→</span>';button.disabled=false;return}if(castState.lines.length>=6){button.innerHTML='六爻已成';button.disabled=true;return}button.disabled=false;if(!ritual){button.innerHTML=`准备第${castState.lines.length+1}爻 <span>→</span>`;return}if(ritual.stepIndex===0&&!ritual.splitReady){button.innerHTML=`请先按住蓍束再松开 · 第${ritual.lineNumber}爻`;button.disabled=true;return}const labels=['分二','挂一','揲四','归奇'];button.innerHTML=`执行${labels[ritual.stepIndex]} · 第${ritual.lineNumber}爻 <span>→</span>`}
function beginRitual(){castState.ritual={lineNumber:castState.lines.length+1,changeNumber:1,stepIndex:0,stalks:49,change:null,history:[]};$('#ritualTitle').textContent=`准备起第${castState.lines.length+1}爻 · 三变十二营`;setTotal(49);paintStalks('leftStalks',49);paintStalks('rightStalks',0);paintStalks('hangStalks',0);paintStalks('discardStalks',0);markOperation('split');setProcedure('第一变 · 按住蓍束，凭感觉松开','分界与策数暂不显露，执行分二时才揭开','');prepareSplitControl();saveCast()}
async function animateCurrentOperation(ritual,operation){
  if(operation==='split')ritual.change=drawYarrowChange(ritual.stalks,ritual.proposedLeft);
  const change=ritual.change;
  if(!change)throw new Error('请先完成分二');
  const leftStrong=$('#leftPile strong'),rightStrong=$('#rightPile strong'),leftMeta=$('#leftPile span'),rightMeta=$('#rightPile span');
  markOperation(operation);
  $('#splitControl').classList.add('hidden');
  if(operation==='split'){
    hideCountingBoard();
    setTotal(ritual.stalks);
    paintStalks('leftStalks',change.left);
    paintStalks('rightStalks',change.right);
    leftStrong.textContent=change.left;
    rightStrong.textContent=change.right;
    leftMeta.textContent='分二 · 天';
    rightMeta.textContent='分二 · 地';
    setProcedure(`第${ritual.changeNumber}变 · 分二`,`${ritual.stalks} 策此时揭开：左 ${change.left}、右 ${change.right}`,'左');
    await wait(1400);
    return;
  }
  if(operation==='hang'){
    hideCountingBoard();
    moveStalks('rightStalks','hangStalks',1,'hanging');
    setTotal(ritual.stalks-1,'待揲');
    rightStrong.textContent=change.rightAfter;
    rightMeta.textContent='挂一后 · 余';
    setProcedure(`第${ritual.changeNumber}变 · 挂一`,`右堆取一策悬于中央：右堆 ${change.right} − 1 = ${change.rightAfter}`,'右');
    await wait(1250);
    return;
  }
  if(operation==='count'){
    renderCountingBoard(change,true);
    setTotal(change.removed,'归奇');
    leftStrong.textContent=change.leftR;
    rightStrong.textContent=change.rightR;
    leftMeta.textContent=`${(change.left-change.leftR)/4}组四策 · 余 ${change.leftR}`;
    rightMeta.textContent=`${(change.rightAfter-change.rightR)/4}组四策 · 余 ${change.rightR}`;
    setProcedure(`第${ritual.changeNumber}变 · 揲四`,`左余 ${change.leftR} + 挂一 1 + 右余 ${change.rightR} = ${change.removed} 策`,'');
    const groups=(change.left-change.leftR+change.rightAfter-change.rightR)/4;
    await wait(Math.min(3200,1100+groups*170));
    return;
  }
  const counting=$('#countingBoard');
  counting?.classList.add('returning');
  await wait(520);
  hideCountingBoard();
  paintStalks('discardStalks',change.removed,'discarded');
  paintStalks('leftStalks',change.remaining);
  paintStalks('rightStalks',0);
  paintStalks('hangStalks',0);
  setTotal(change.remaining);
  leftStrong.textContent=change.remaining;
  rightStrong.textContent='—';
  leftMeta.textContent=`归奇 · 旁置 ${change.removed} 策`;
  rightMeta.textContent='余下合拢';
  renderChangeLedger(ritual,change);
  setProcedure(`第${ritual.changeNumber}变 · 归奇`,`${change.before} − (${change.leftR} + 1 + ${change.rightR}) = ${change.remaining} 策`,'');
  await wait(1200);
}
async function castLine(){if(castState.working||!castState.confirmed||castState.lines.length>=6)return;if(!castState.prepared){const runId=++castState.runId;castState.working=true;$('#castButton').disabled=true;$('.yarrow-stage').classList.add('is-calculating');moveStalks('leftStalks','taijiStalks',1,'discarded');setTotal(49);setProcedure('大衍之数五十，其用四十有九','你亲自取出一策不用，象太极；余四十九策入筮','');await wait(1500);if(castState.runId!==runId)return;castState.working=false;castState.prepared=true;$('.yarrow-stage').classList.remove('is-calculating');beginRitual();updateCastButton();saveCast();return}if(!castState.ritual){beginRitual();updateCastButton();return}if(castState.ritual.stepIndex===0&&!castState.ritual.splitReady)return;const ritual=castState.ritual,runId=++castState.runId,operation=['split','hang','count','return'][ritual.stepIndex];castState.working=true;$('#castButton').disabled=true;$('.yarrow-stage').classList.add('is-calculating');try{await animateCurrentOperation(ritual,operation);if(castState.runId!==runId)return;castState.working=false;ritual.stepIndex++;if(operation==='return'){ritual.history.push({...ritual.change});ritual.stalks=ritual.change.remaining;ritual.change=null;if(ritual.changeNumber===3){const val=ritual.stalks/4;castState.lines.push({value:val,changes:ritual.history});castState.ritual=null;$('#lineCount').textContent=`${castState.lines.length} / 6 爻`;$('#ritualTitle').textContent=castState.lines.length===6?'六爻已成 · 可观本卦与变卦':`第${castState.lines.length}爻已成 · 请继续`;$('#stageResult').textContent=`${ritual.history.map(item=>item.before+'−'+item.removed+'='+item.remaining).join('；')}；${ritual.stalks}÷4=${val} · ${lineName(val)}`;renderRecords();if(castState.lines.length===6)showResult()}else{ritual.changeNumber++;ritual.stepIndex=0;$('#stageResult').textContent=`第${ritual.changeNumber-1}变完成 · 余 ${ritual.stalks} 策`}}if(castState.ritual){const next=['分二','挂一','揲四','归奇'][castState.ritual.stepIndex];$('#stageHint').textContent=`下一步：第${castState.ritual.changeNumber}变 · ${next}`;markOperation(['split','hang','count','return'][castState.ritual.stepIndex]);prepareSplitControl()}else{markOperation('')}$('.yarrow-stage').classList.remove('is-calculating');updateCastButton();saveCast()}catch(error){if(castState.runId===runId){castState.working=false;$('.yarrow-stage').classList.remove('is-calculating');$('#stageHint').textContent='本步未完成，请重新点击';updateCastButton();console.error(error)}}}
const trigramByLines={'111':'天','110':'泽','101':'火','100':'雷','011':'风','010':'水','001':'山','000':'地'};
function hexIndexForLines(lines,changed=false){const bits=lines.map(line=>{if(changed&&line.value===6)return 1;if(changed&&line.value===9)return 0;return line.value===7||line.value===9?1:0});const lower=trigramByLines[bits.slice(0,3).join('')],upper=trigramByLines[bits.slice(3,6).join('')];return hexagrams.findIndex(hexagram=>hexagram[6]===upper&&hexagram[7]===lower)}
function readingRule(moving,originalIndex){const positions=moving.map(index=>index+1);if(moving.length===0)return {text:'六爻皆静：以本卦卦辞为主要阅读依据。',primary:[]};if(moving.length===1)return {text:`一爻变：以本卦第${positions[0]}爻爻辞为主。`,primary:moving};if(moving.length===2)return {text:`二爻变：同读本卦第${positions.join('、')}爻，以上位动爻为主。`,primary:moving};if(moving.length===3)return {text:'三爻变：合读本卦与变卦卦辞，以本卦为主。',primary:[]};const still=[0,1,2,3,4,5].filter(index=>!moving.includes(index));if(moving.length===4)return {text:`四爻变：读变卦第${still.map(index=>index+1).join('、')}爻，以较下的一爻为主。`,primary:still,fromChanged:true};if(moving.length===5)return {text:`五爻变：以变卦唯一不变的第${still[0]+1}爻为主。`,primary:still,fromChanged:true};const special=originalIndex===0||originalIndex===1;return {text:special?'六爻皆变：乾坤依用九、用六，并参看变卦。':'六爻皆变：以变卦卦辞为主。',primary:[],fromChanged:true}}
function showResult(){const idx=hexIndexForLines(castState.lines),changedIndex=hexIndexForLines(castState.lines,true);if(idx<0||changedIndex<0){console.error('卦象映射失败');return}selectedHex=idx;const hexagram=hexagrams[idx],changed=hexagrams[changedIndex],moving=castState.lines.map((line,index)=>line.value===6||line.value===9?index:-1).filter(index=>index>=0),rule=readingRule(moving,idx),source=hexagramTexts?.hexagrams?.[idx],changedSource=hexagramTexts?.hexagrams?.[changedIndex];$('#resultCard').classList.remove('hidden');$('#resultPrimary').textContent=hexagram[1];$('#resultChanged').textContent=changed[1];$('#resultName').textContent=`${hexagram[2]} → ${changed[2]}`;$('#resultSummary').textContent=moving.length?`动爻：${moving.map(index=>['初','二','三','四','五','上'][index]).join('、')}爻`:'六爻皆静';$('#stageHint').textContent='六爻既成，以下列规则研读经文';$('#readingPanel').classList.remove('hidden');$('#readingTitle').textContent=`${hexagram[2]}之${changed[2]}`;$('#readingQuestion').textContent=`所问：${castState.question}`;$('#readingFocus').textContent=`${rule.text} 本页采用朱熹《易学启蒙》通行变爻取法；此为后世读法，不冒充《周易》经文原句。`;const originalLines=moving.length<=2?moving.map(index=>source?.lines?.[index]).filter(Boolean):moving.length===6?[source?.lines?.find(line=>line.label.startsWith('用'))].filter(Boolean):[],changedFocus=rule.fromChanged?rule.primary.map(index=>changedSource?.lines?.[index]).filter(Boolean):[];$('#readingColumns').innerHTML=`<article class="reading-column"><h3>${hexagram[1]} ${hexagram[2]}</h3><small>本卦 · 当前处境</small><p>${textHtml(source?.text||hexagram[4])}</p>${originalLines.length?`<div class="reading-lines">${originalLines.map(line=>`<div class="reading-line"><b>${line.label}</b>${textHtml(line.text)}</div>`).join('')}</div>`:''}</article><article class="reading-column"><h3>${changed[1]} ${changed[2]}</h3><small>变卦 · 变化所向</small><p>${textHtml(changedSource?.text||changed[4])}</p>${changedFocus.length?`<div class="reading-lines">${changedFocus.map(line=>`<div class="reading-line"><b>${line.label}</b>${textHtml(line.text)}</div>`).join('')}</div>`:''}</article>`;saveReadingHistory(idx,changedIndex,moving);saveCast()}
function validateQuestion(){const value=$('#questionInput').value.trim(),feedback=$('#questionFeedback'),button=$('#confirmQuestion');let message='',valid=true;if(value.length<8){valid=false;message='问题还不够具体，请写明情境和你想辨明的方向。'}else if(value.length>100){valid=false;message='请收束到一件事，控制在 100 字以内。'}else if((value.match(/[？?]/g)||[]).length>1||/[、，,].*(还是|或者)/.test(value)){valid=false;message='这里可能包含多个问题，请一次只保留一件事。'}else if(/^(吉不吉|能不能|会不会|好不好)[？?]?$/.test(value)){valid=false;message='试着改问“面对这件事，我应当注意什么？”'}else{message='问题清楚。确认后将锁定，直到本次仪式结束。'}feedback.textContent=message;feedback.className=valid?'valid':'invalid';button.disabled=!valid;return valid}
function confirmQuestion(){if(!validateQuestion())return;castState.question=$('#questionInput').value.trim();castState.sessionId=newSessionId();castState.confirmed=true;castState.prepared=false;$('#questionInput').readOnly=true;$('#consultationGuide').classList.add('confirmed');$('#confirmQuestion').disabled=true;$('#confirmQuestion').textContent='问题已确认';$('#lockedQuestion').textContent=`所问：${castState.question}`;$('#lockedQuestion').classList.remove('hidden');$('#ritualTitle').textContent='五十策已备 · 请亲手虚一';paintStalks('leftStalks',50);paintStalks('rightStalks',0);paintStalks('taijiStalks',0);paintStalks('hangStalks',0);paintStalks('discardStalks',0);setTotal(50);setProcedure('先从五十策中取出一策不用','此一策象太极，不再参与其后的十八变','');updateCastButton();document.querySelector('.ritual-panel').scrollIntoView({behavior:'smooth',block:'start'});saveCast()}
function restoreCast(){let saved=null,source='';for(const key of ['guanxiang-cast-v3','guanxiang-cast-v2','guanxiang-cast']){try{const candidate=JSON.parse(localStorage.getItem(key)||'null');if(candidate){saved=candidate;source=key;break}}catch(error){console.warn(`${key} 无法读取`,error)}}if(!saved?.confirmed||typeof saved.question!=='string'||!saved.question.trim())return;const lines=Array.isArray(saved.lines)?saved.lines:[];if(lines.length>6||!lines.every(validLine)||!validRitual(saved.ritual||null,lines.length)){showNotice('检测到一份损坏的起卦进度，已停止恢复；可以重新开始一次占问。');return}castState={lines,working:false,runId:0,ritual:saved.ritual||null,confirmed:true,prepared:Boolean(saved.prepared),question:saved.question.trim(),sessionId:typeof saved.sessionId==='string'&&saved.sessionId?saved.sessionId:newSessionId()};if(source!=='guanxiang-cast-v3')saveCast();$('#questionInput').value=castState.question;$('#questionInput').readOnly=true;$('#consultationGuide').classList.add('confirmed');$('#confirmQuestion').disabled=true;$('#confirmQuestion').textContent='问题已确认';$('#lockedQuestion').textContent=`所问：${castState.question}`;$('#lockedQuestion').classList.remove('hidden');$('#lineCount').textContent=`${castState.lines.length} / 6 爻`;renderRecords();if(castState.lines.length===6){$('#ritualTitle').textContent='六爻已成 · 可继续研读';updateCastButton();showResult();return}if(!castState.prepared){$('#ritualTitle').textContent='五十策已备 · 请亲手虚一';paintStalks('leftStalks',50);setTotal(50);setProcedure('继续本次仪式：先虚一策','进度已从本机恢复','');updateCastButton();return}if(!castState.ritual){$('#ritualTitle').textContent=`第${castState.lines.length}爻已成 · 请准备下一爻`;paintStalks('leftStalks',49);setTotal(49);setProcedure('本次进度已恢复','点击“准备下一爻”继续','');updateCastButton();return}const ritual=castState.ritual,change=ritual.change;$('#ritualTitle').textContent=`继续第${ritual.lineNumber}爻 · 第${ritual.changeNumber}变`;if(ritual.stepIndex===0){paintStalks('leftStalks',ritual.stalks);paintStalks('rightStalks',0);setTotal(ritual.stalks);setProcedure(`继续第${ritual.changeNumber}变 · 分二`,ritual.splitReady?'分界已经保留，可直接执行分二':'请在蓍草束上重新落指','');prepareSplitControl()}else if(change){paintStalks('leftStalks',change.left);paintStalks('rightStalks',ritual.stepIndex>=2?change.rightAfter:change.right);paintStalks('hangStalks',ritual.stepIndex>=2?1:0,'hanging');setTotal(ritual.stepIndex>=2?ritual.stalks-1:ritual.stalks);const next=['分二','挂一','揲四','归奇'][ritual.stepIndex];setProcedure(`继续第${ritual.changeNumber}变 · ${next}`,'上一步已保存在本机','');markOperation(['split','hang','count','return'][ritual.stepIndex])}updateCastButton()}
function resetCast(){castState={lines:[],working:false,runId:castState.runId+1,ritual:null,confirmed:false,prepared:false,question:'',sessionId:''};try{['guanxiang-cast','guanxiang-cast-v2','guanxiang-cast-v3'].forEach(key=>localStorage.removeItem(key))}catch(error){console.warn('起卦进度未能清除',error)}$('#questionInput').value='';$('#questionInput').readOnly=false;$('#consultationGuide').classList.remove('confirmed');$('#confirmQuestion').textContent='确认问题，进入仪式';$('#lockedQuestion').classList.add('hidden');$('#readingPanel').classList.add('hidden');$('#lineCount').textContent='0 / 6 爻';$('#ritualTitle').textContent='请先确认此次所问';$('#castButton').innerHTML='请先确认问题';setProcedure('问题确认后，完整仪式将在这里开始','');markOperation('');$('#splitControl').classList.add('hidden');['leftStalks','rightStalks','taijiStalks','hangStalks','discardStalks'].forEach(id=>paintStalks(id,0));setTotal('—');$('#leftPile strong').textContent='—';$('#rightPile strong').textContent='—';$('#leftPile span').textContent='待分';$('#rightPile span').textContent='待分';$('.yarrow-stage').classList.remove('is-calculating');$('#resultCard').classList.add('hidden');renderRecords();validateQuestion();updateCastButton()}
document.addEventListener('DOMContentLoaded',()=>{
  initTheme();
  renderCalendarMeta();
  try{const savedMode=localStorage.getItem('guanxiang-reading-mode');if(['ancient','modern'].includes(savedMode))readingMode=savedMode}catch(error){console.warn('阅读模式未能读取',error)}
  ensureDivinationPhases();
  ensureRitualEnhancements();
  renderHexList();
  renderHexDetail();
  renderClassics();
  renderPrinciples();
  renderHistory();
  validateQuestion();
  restoreCast();
  renderRitualProgress();
  renderChangeLedger();
  if(castState.ritual?.stepIndex===0)setProcedure(`继续第${castState.ritual.changeNumber}变 · 分二`,castState.ritual.splitReady?'分界已经保留，左右策数仍未揭开':'按住蓍束，凭感觉松开','');
  if(castState.ritual?.stepIndex===3&&castState.ritual.change)renderCountingBoard(castState.ritual.change,false);
  setDivinationPhase(castState.lines.length>=6?'result':castState.confirmed?'cast':'prepare',false,false);
  applyRoute();
  loadTenWings();
  $$('[data-view]').forEach(button=>button.addEventListener('click',()=>nav(button.dataset.view)));
  $$('[data-cast-phase]').forEach(button=>button.addEventListener('click',()=>setDivinationPhase(button.dataset.castPhase)));
  $('#hexSearch').addEventListener('input',renderHexList);
  $('#wingSearch').addEventListener('input',renderClassics);
  $$('[data-reading-mode]').forEach(button=>button.addEventListener('click',()=>{readingMode=button.dataset.readingMode;try{localStorage.setItem('guanxiang-reading-mode',readingMode)}catch(error){console.warn('阅读模式未能保存',error)}renderClassics()}));
  $('#bookmarkWing').addEventListener('click',()=>{if(!tenWings?.wings?.[selectedWing])return;const id=tenWings.wings[selectedWing].id,bookmarks=wingBookmarks(),next=bookmarks.includes(id)?bookmarks.filter(item=>item!==id):[...bookmarks,id];try{localStorage.setItem('guanxiang-wing-bookmarks',JSON.stringify(next))}catch(error){console.warn('收藏未能保存',error)}renderClassics()});
  $$('.filter-button').forEach(button=>button.addEventListener('click',()=>{$$('.filter-button').forEach(item=>item.classList.remove('active'));button.classList.add('active');filter=button.dataset.filter;renderHexList()}));
  $('#questionInput').addEventListener('input',validateQuestion);
  $$('[data-question-example]').forEach(button=>button.addEventListener('click',()=>{$('#questionInput').value=button.dataset.questionExample;validateQuestion()}));
  $('#confirmQuestion').addEventListener('click',()=>{confirmQuestion();if(castState.confirmed)setDivinationPhase('cast')});
  $('#splitChooser').addEventListener('pointerdown',beginSplitFeeling);
  $('#splitChooser').addEventListener('pointermove',trackSplitFeeling);
  $('#splitChooser').addEventListener('pointerup',finishSplitFeeling);
  $('#splitChooser').addEventListener('pointercancel',cancelSplitFeeling);
  $('#splitChooser').addEventListener('keydown',beginSplitFeeling);
  $('#splitChooser').addEventListener('keyup',finishSplitFeeling);
  $('#castButton').addEventListener('click',castLine);
  $('#resetButton').addEventListener('click',()=>{if(castState.confirmed||castState.lines.length||castState.ritual){const dialog=$('#resetDialog');if(typeof dialog.showModal==='function')dialog.showModal();else if(confirm('舍弃本次占问进度？')){resetCast();setDivinationPhase('prepare')}}else{resetCast();setDivinationPhase('prepare')}});
  $('#confirmReset').addEventListener('click',()=>{resetCast();setDivinationPhase('prepare')});
  $('#resultRead').addEventListener('click',()=>{nav('hexagrams');renderHexList();renderHexDetail()});
  $('#themeToggle').addEventListener('click',()=>applyTheme(document.body.classList.contains('dark-mode')?'light':'dark',true));
});
window.addEventListener('hashchange',applyRoute);
document.addEventListener('DOMContentLoaded',()=>{if(!castState.confirmed)return;$('#questionFeedback').textContent='问题已锁定，当前仪式进度已保存在本机。';$('#questionFeedback').className='valid';if(castState.prepared)paintStalks('taijiStalks',1,'discarded')});
